import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.io.InputStream;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskF solver = new TaskF();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskF {
        int MAX = (int) (1e9);

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int k = in.nextInt();
            ArrayList<int[]> interval = new ArrayList<>();
            for (int i = 0; i < k; i++) {
                interval.add(new int[]{in.nextInt(), in.nextInt()});
            }
            interval.add(new int[]{2 * N, 2 * N});
            int cur = 0;
            int[] dp0 = new int[N + 1];
            int[] dp1 = new int[N + 1];
            Arrays.fill(dp0, MAX);
            Arrays.fill(dp1, MAX);
            dp0[0] = 0;
            for (int i = 0; i < interval.size(); i++) {
                int[] seg = interval.get(i);
                int diff = seg[0] - cur;
                for (int j = N; j >= 0; j--) {
                    int prev = j - diff;
                    dp0[j] = (prev >= 0) ? dp0[prev] : MAX;
                }
                cur = seg[1];
                int sz = seg[1] - seg[0];
                for (int j = N; j >= 0; j--) {
                    int[] put = new int[2];
                    for (int z = 0; z <= 1; z++) {
                        int[] curDp = (z == 0) ? dp0 : dp1;
                        int[] otherDp = (z == 0) ? dp1 : dp0;
                        int twoSwaps = query(curDp, j - sz, j, MAX);
                        int oneSwap = query(otherDp, j - sz, j, MAX);
                        int noSwap;
                        if (z == 1) {
                            noSwap = curDp[j];
                        } else {
                            noSwap = (j - sz >= 0) ? curDp[j - sz] : MAX;
                        }
                        put[z] = Math.min(twoSwaps + 2, Math.min(oneSwap + 1, noSwap));
                    }
                    dp0[j] = put[0];
                    dp1[j] = put[1];
                }
            }
            int ans = Math.min(dp0[N], dp1[N]);
            if (ans >= MAX) {
                out.println("Hungry");
            } else {
                out.println("Full");
                out.println(ans);
            }
        }

        private int query(int[] arr, int l, int r, int MAX) {
            if (r < 0) return MAX;
            l = Math.max(0, l);
            if (l > r) return MAX;
            int min = MAX;
            for (int i = l; i <= r; i++) {
                min = Math.min(min, arr[i]);
            }
            return min;
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
